Lemma p2i_spec : forall p n sh acc r,
  p2i p n sh acc = Some r -> φ sh + Z.of_nat n <= 62 -> 0 <= φ acc < 2 ^ φ sh ->
  φ r = φ acc + Zpos p * 2 ^ φ sh /\ Zpos p < 2 ^ Z.of_nat n.
