  (forall u, a <= u < a + Z.of_nat n -> find_segment segs u 1 = Some seg) ->
  seg_readable seg = true -> 0 <= a -> a + Z.of_nat n < 2 ^ 62 -> φ o = a - Z.of_N (seg_base seg) -> Z.of_N (seg_base seg) <= a ->
  img_goI (seg_bytes seg) o n = img_bytes segs a n.
